package net.minecraft.world.level.levelgen;

/**
 * The stand-in for the game's WorldGenerationContext: a type. The world is generated by Horizon, which never asks a
 * mod's generation for it: what a context answers refuses, saying so.
 */
public class WorldGenerationContext {
    private WorldGenerationContext() {}

    public int getMinGenY() {
        throw new UnsupportedOperationException("a world generation context isn't modelled: Horizon generates the world (horizon-port-neoforge)");
    }

    public int getGenDepth() {
        throw new UnsupportedOperationException("a world generation context isn't modelled: Horizon generates the world (horizon-port-neoforge)");
    }
}
